@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--gold:#e7b45b;--red:#e54343;--ink:#09070d;--muted:#a59ba5}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#09070d;color:#fff;font-family:'DM Sans',sans-serif;touch-action:none}#game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:#08070d}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.grain,.vignette{position:absolute;inset:0;pointer-events:none}.grain{opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E");mix-blend-mode:screen}.vignette{background:radial-gradient(ellipse at 50% 48%,transparent 34%,rgba(4,3,8,.35) 78%,rgba(3,2,5,.9) 140%)}
#hud{position:absolute;inset:0 0 auto;height:154px;padding:26px 4.3%;z-index:2;pointer-events:none;background:linear-gradient(180deg,rgba(8,6,12,.82),transparent)}.hidden{display:none!important}.brand-mark{position:absolute;left:4.3%;top:24px;display:flex;align-items:center;gap:11px}.sigil{color:var(--gold);font-size:28px;text-shadow:0 0 17px #e6a84d}.brand-mark b{display:block;font:800 19px 'Barlow Condensed';letter-spacing:.18em}.brand-mark small{display:block;color:#a89ba7;font-size:8px;letter-spacing:.23em}.chapter{position:absolute;left:50%;transform:translateX(-50%);top:25px;text-align:center}.chapter small,.chapter strong{display:block}.chapter small{color:#c19a62;font:600 9px 'Barlow Condensed';letter-spacing:.24em}.chapter strong{font:700 13px 'Barlow Condensed';letter-spacing:.14em;margin-top:3px}.icon-btn{pointer-events:auto;position:absolute;right:4.3%;top:24px;width:36px;height:36px;border:1px solid #fff3;background:#17121b;color:#fff;font-size:16px;border-radius:50%;cursor:pointer}.boss-hud{position:absolute;top:80px;left:50%;transform:translateX(-50%);width:min(380px,40vw);text-align:center}.boss-line{display:flex;align-items:baseline;justify-content:center;gap:8px}.boss-line span{font:700 18px 'Barlow Condensed';letter-spacing:.16em}.boss-line small{color:#d5a866;font:600 9px 'Barlow Condensed';letter-spacing:.16em}.meter{height:6px;background:#ffffff20;border:1px solid #ffffff25;transform:skewX(-14deg);overflow:hidden}.boss-meter{margin-top:7px}.meter i{height:100%;width:100%;display:block;transition:width .2s;background:linear-gradient(90deg,#9f222d,#f15c4a);box-shadow:0 0 14px #f04453}.boss-meter i{float:right}#phase-label{font:600 8px 'Barlow Condensed';letter-spacing:.2em;color:#c3a6a7;margin-top:5px}.hero-hud{position:absolute;left:4.3%;top:91px;width:min(220px,30vw)}.hero-name{font:700 12px 'Barlow Condensed';letter-spacing:.16em}.hero-name span{color:#a99daa;font-size:9px;margin-left:5px}.hero-meter{height:5px;margin-top:5px}.hero-meter i{background:linear-gradient(90deg,#9c2935,#f3424d);box-shadow:0 0 12px #f33}.resource-row{display:flex;align-items:center;gap:7px;margin-top:7px;font:700 8px 'Barlow Condensed';letter-spacing:.15em;color:#dfa67c}.resource-row b{font-size:9px;color:#fff}.wrath-meter{width:90px;height:4px}.wrath-meter i{background:linear-gradient(90deg,#ee652b,#ffcb64);box-shadow:0 0 10px #ff8a28}
.screen{position:absolute;inset:0;z-index:4;display:flex;align-items:center;padding:0 10%;background:linear-gradient(90deg,rgba(8,6,12,.93) 0%,rgba(8,6,12,.76) 34%,rgba(8,6,12,.12) 76%,transparent)}.title-copy{margin-top:1vh;max-width:510px}.eyebrow{font:700 10px 'Barlow Condensed';letter-spacing:.3em;color:#dca95e}.title-copy h1{font:900 clamp(76px,12vw,154px)/.77 'Barlow Condensed';letter-spacing:-.045em;margin:19px 0 11px;text-shadow:0 10px 38px #000}.title-copy h1 span{color:#d54a44}.title-sub{font:600 13px 'Barlow Condensed';letter-spacing:.54em;color:#edc478;margin-left:6px}.title-copy p{color:#c1b6c0;font-size:14px;line-height:1.75;margin:26px 0 25px}.primary-btn,.secondary-btn{border:0;cursor:pointer;color:#fff;font:700 11px 'Barlow Condensed';letter-spacing:.18em;padding:15px 20px;transition:.2s}.primary-btn{background:linear-gradient(110deg,#b7363b,#8d2732);box-shadow:0 8px 26px #a9303b42;border:1px solid #ff7b6550}.primary-btn:hover{filter:brightness(1.25);transform:translateY(-2px)}.primary-btn span{font-size:16px;margin-left:17px}.microcopy{color:#786e79;font-size:9px;letter-spacing:.06em;margin-top:18px}.title-meta{position:absolute;bottom:6%;left:10%;display:flex;align-items:center;gap:12px;color:#988d99;font:600 9px 'Barlow Condensed';letter-spacing:.18em}.title-meta i{width:55px;height:1px;background:#b98f58}.chapter-card,.modal-card,.result-card{width:min(490px,90vw);padding:36px 39px;background:linear-gradient(145deg,rgba(26,20,31,.94),rgba(12,9,16,.91));border:1px solid #e6ba7433;box-shadow:0 25px 90px #0009;backdrop-filter:blur(14px)}.chapter-card h2,.modal-card h2,.result-card h2{font:900 clamp(50px,8vw,82px)/.85 'Barlow Condensed';letter-spacing:.02em;margin:22px 0 5px;text-shadow:0 0 25px #e0ad6655}.chapter-card h3{margin:0;color:#e2b968;font:600 12px 'Barlow Condensed';letter-spacing:.26em}.chapter-card p,.modal-card p,.result-card p{color:#bcb1bc;font-size:13px;line-height:1.8;margin:23px 0 14px}.chapter-card blockquote{margin:0 0 25px;padding-left:14px;border-left:2px solid #bd4d4a;color:#e5c4bc;font:italic 15px/1.6 'Barlow Condensed'}.modal-card{text-align:center}.modal-card h2{font-size:66px}.button-row{display:flex;gap:10px;justify-content:center;margin:24px 0}.secondary-btn{background:#ffffff0b;border:1px solid #ffffff2b}.controls-note{color:#8f8490;font-size:9px;line-height:2.1;letter-spacing:.08em}.controls-note b{color:#e4bd7b}.result-card h2{font-size:61px}.reward-chip{display:flex;align-items:center;gap:13px;text-align:left;padding:13px 15px;margin:20px 0 25px;border:1px solid #e8bc6738;background:#d9a74f0d}.reward-chip>span{font-size:23px;color:#eac16e}.reward-chip small,.reward-chip b{display:block}.reward-chip small{color:#c4a76f;font:600 8px 'Barlow Condensed';letter-spacing:.22em}.reward-chip b{font:700 13px 'Barlow Condensed';letter-spacing:.1em;margin-top:4px}.toast{position:absolute;z-index:3;top:23%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.35s;pointer-events:none;color:#f1d59c;background:#211523c9;border:1px solid #d5a75345;padding:10px 18px;font:600 10px 'Barlow Condensed';letter-spacing:.2em}.toast.show{opacity:1;transform:translate(-50%,0)}.combat-caption{position:absolute;z-index:2;bottom:16%;left:50%;transform:translateX(-50%);text-align:center;max-width:90vw;color:#f5ded3;text-shadow:0 2px 8px #000;font:600 20px 'Barlow Condensed';letter-spacing:.08em;opacity:0;transition:opacity .4s;pointer-events:none}.combat-caption.show{opacity:1}
#controls{position:absolute;inset:auto 0 0;z-index:3;height:210px;pointer-events:none}.mobile-pad,.action-pad{position:absolute;bottom:26px;pointer-events:auto}.mobile-pad{left:28px;width:126px;height:126px}.action-pad{right:25px;width:200px;height:160px}.action-pad button{position:absolute;pointer-events:auto;border-radius:50%;background:#130f19c9;border:1px solid #ffffff55;color:#fff;font:700 9px 'Barlow Condensed';letter-spacing:.08em;touch-action:none;box-shadow:0 4px 14px #0007}.touch-action:active{transform:scale(.92);filter:brightness(1.5)}.touch-action.light{right:0;bottom:52px;width:58px;height:58px;border-color:#e66a5e}.touch-action.heavy{right:65px;bottom:8px;width:53px;height:53px;border-color:#e6b45e}.touch-action.dodge{right:73px;bottom:78px;width:44px;height:44px}.touch-action.guard{right:123px;bottom:35px;width:42px;height:42px}.touch-action.wrath{right:8px;bottom:0;width:42px;height:42px;border-color:#ed6845;color:#ffad6e}.#stick-base{position:absolute;inset:0;border:1px solid #ffffff3b;background:#130f1988;border-radius:50%;box-shadow:0 0 30px #0007;touch-action:none}#stick-base:after{content:'';position:absolute;inset:15px;border:1px solid #ffffff19;border-radius:50%}#stick-knob{position:absolute;left:50%;top:50%;width:49px;height:49px;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle at 35% 30%,#78677a,#352a3b);border:1px solid #ffffff69;box-shadow:0 3px 14px #0008;z-index:1}.screen.hidden{display:none}.screen:not(#title-screen){background:rgba(5,3,8,.48);backdrop-filter:blur(4px)}
@media (pointer:fine){#controls{display:none!important}}@media(max-width:700px){#hud{padding:18px 4%;height:126px}.brand-mark{left:4%;top:18px}.brand-mark b{font-size:16px}.brand-mark small{font-size:7px}.chapter{top:20px}.chapter strong{font-size:10px}.icon-btn{right:4%;top:18px;width:32px;height:32px}.boss-hud{top:70px;width:50vw}.boss-line span{font-size:14px}.boss-line small{font-size:7px}.hero-hud{top:80px;left:4%;width:26vw}.hero-name{font-size:10px}.hero-name span{display:none}.hero-meter{margin-top:4px}.resource-row{gap:4px}.wrath-meter{width:45px}.screen{padding:0 7%;background:linear-gradient(90deg,rgba(7,5,10,.88),rgba(8,6,12,.55) 60%,transparent)}.title-copy{max-width:390px}.title-copy h1{font-size:clamp(72px,19vw,125px)}.title-copy p{font-size:12px;margin:20px 0}.eyebrow{font-size:9px}.title-meta{left:7%;bottom:4%}.chapter-card,.modal-card,.result-card{padding:27px 24px}.chapter-card h2{font-size:62px}.combat-caption{bottom:23%;font-size:16px}#controls{height:175px}.mobile-pad{left:17px;bottom:15px;width:112px;height:112px}.action-pad{right:12px;bottom:12px;transform:scale(.9);transform-origin:bottom right}.button-row{flex-direction:column}.button-row button{width:100%}}@media(max-height:500px){.title-copy h1{font-size:75px;margin:12px 0}.title-copy p{margin:13px 0}.title-meta{bottom:2%}.chapter-card{padding:20px 26px}.chapter-card h2{font-size:54px}.chapter-card p{margin:13px 0}.chapter-card blockquote{margin-bottom:13px}.primary-btn{padding:12px 17px}}

(() => {
'use strict';
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d',{alpha:false});
const $=id=>document.getElementById(id);
const deities=[
 {name:'AUREX',epithet:'GOD OF WAR',place:'THE WARTHRONE',realm:'A shattered golden citadel suspended above a field of broken spears.',intro:'The armies kneel as their god descends. Aurex remembers the warrior who once stood at his side—and the hand that struck first.',quote:'“You were my finest blade, Vael. You should have stayed broken.”',reward:'SIGIL OF THE WARTHRONE',color:'#f0b957',dark:'#733f32',style:'war',music:110},
 {name:'VORAGOS',epithet:'GOD OF DESTRUCTION',place:'THE CINDER WORLD',realm:'A dying planet, split open to its molten heart.',intro:'The world cracks beneath a mountain of living ember. Voragos does not speak; the planet speaks through him.',quote:'“Every ending is a beginning. Let me show you.”',reward:'HEART OF THE CINDER WORLD',color:'#ff633a',dark:'#8c2424',style:'fire',music:80},
 {name:'NYTHERA',epithet:'GODDESS OF DEATH',place:'THE VEIL OF THE DEAD',realm:'A cathedral of black glass where lost souls drift like pale stars.',intro:'A thousand stolen voices rise from the veil. Nythera has been collecting the dead—and one of them knows Vael’s true name.',quote:'“I have kept your ending safe for an age.”',reward:'VEIL-SHARD OF THE LOST',color:'#a875ee',dark:'#342255',style:'death',music:72},
 {name:'ZERAKH',epithet:'GOD OF TIME',place:'THE HOURGLASS THRONE',realm:'A fractured clockwork temple caught between one heartbeat and the next.',intro:'The hourglass turns. Zerakh appears in the memory of the battle before he appears in the battle itself.',quote:'“I have killed you in every future. This is the one where I hesitate.”',reward:'SAND OF THE FIRST HOUR',color:'#72d5d3',dark:'#285572',style:'time',music:120},
 {name:'THALMOR',epithet:'GOD OF THE ABYSS',place:'THE DROWNED BELOW',realm:'A small obsidian platform over an ocean with no horizon.',intro:'Something vast moves beneath the water. The abyss exhales, and the shoreline rises to meet its ancient master.',quote:'“You cannot kill what the dark has already swallowed.”',reward:'ABYSSAL TIDE-SEAL',color:'#43c5cb',dark:'#153947',style:'abyss',music:66},
 {name:'SOLARION',epithet:'GOD OF LIGHT',place:'THE SUNFALL SPIRE',realm:'A floating observatory in the corona of a wounded star.',intro:'A star takes a human shape. Solarion calls the burning of a thousand worlds mercy—and asks Vael to kneel in its light.',quote:'“I will make your pain beautiful.”',reward:'SHARD OF THE WOUNDED SUN',color:'#ffe88b',dark:'#b65941',style:'light',music:132},
 {name:"DRAK’THUL",epithet:'GOD OF CHAOS',place:'THE UNMADE',realm:'A battlefield stitched together from places that should never touch.',intro:'The arena changes when you look away. Drak’Thul laughs with Vael’s own voice, wearing the shapes of everything he fears.',quote:'“Which of us is the memory?”',reward:'CHAOS-KNOT OF THE UNMADE',color:'#ef66d0',dark:'#4c2768',style:'chaos',music:96},
 {name:'ELYNDRA',epithet:'GODDESS OF CREATION',place:'THE FIRST GARDEN',realm:'A celestial garden of unfinished worlds, held in the hand of its architect.',intro:'Elyndra shapes mountains from dust as she speaks. Her constructs protect her—not because she commands them, but because they love her.',quote:'“I made them to outlive us. I did not make them to suffer.”',reward:'SEED OF THE FIRST WORLD',color:'#81e0a1',dark:'#2f6657',style:'creation',music:104},
 {name:'OMNIVAR',epithet:'THE SUPREME DEITY',place:'THE THRONE BEYOND',realm:'The first throne, at the center of the fracture where creation began.',intro:'The truth is not a weapon. The Nine did not betray Vael: they sealed away the part of him that would unmake creation. Omnivar is the name he gave that fear.',quote:'“You were the tenth. You were the hand that made us.”',reward:'THE LAST NAME — CREATION RESTORED',color:'#e4d7ff',dark:'#6c4a91',style:'final',music:58}
];
const roman=['I','II','III','IV','V','VI','VII','VIII','IX'];
const state={mode:'title',index:0,hp:100,wrath:0,bossHp:100,phase:1,player:{x:0,z:.12,face:1,anim:'idle',animT:0,attackCd:0,invuln:0,guard:false,combo:0,comboT:0},boss:{x:0,z:-.28,anim:'idle',animT:0,attackT:2.2,windup:0,attack:null,stun:0},time:0,last:0,shake:0,flash:0,particles:[],projectiles:[],captions:[],arenaSeed:1,moveX:0,moveY:0,keys:{},slow:0,phaseIntro:0,kills:0,storyStart:false};
const saved=Number(localStorage.getItem('godfall-progress')||0);state.index=Math.min(saved,8);
const screens=['title-screen','chapter-screen','pause-screen','result-screen'];
const showScreen=id=>screens.forEach(x=>$(x).classList.toggle('hidden',x!==id));
function startChapter(){let d=deities[state.index];state.mode='intro';state.hp=100;state.wrath=state.index?Math.min(25+state.index*5,65):0;state.bossHp=100;state.phase=1;state.time=0;state.shake=0;state.flash=0;state.particles=[];state.projectiles=[];state.player={x:0,z:.12,face:1,anim:'idle',animT:0,attackCd:0,invuln:0,guard:false,combo:0,comboT:0};state.boss={x:0,z:-.28,anim:'idle',animT:0,attackT:2.1,windup:0,attack:null,stun:0};state.arenaSeed=state.index+19;updateHud();$('intro-kicker').textContent=`CHAPTER ${roman[state.index]} · ${d.place}`;$('intro-name').textContent=d.name;$('intro-epithet').textContent=d.epithet;$('intro-copy').textContent=d.intro;$('intro-quote').textContent=d.quote;showScreen('chapter-screen');$('hud').classList.add('hidden');$('controls').classList.add('hidden')}
function beginFight(){state.mode='fight';showScreen('none');$('hud').classList.remove('hidden');$('controls').classList.remove('hidden');caption(`“${deities[state.index].quote.slice(1).split('”')[0]}”`,2400);showToast('DIVINE WRATH AWAKENS');}
function updateHud(){const d=deities[state.index];$('chapter-num').textContent=roman[state.index];$('chapter-title').textContent=d.place;$('boss-title').textContent=d.name;$('boss-epithet').textContent=d.epithet;$('boss-fill').style.width=`${Math.max(0,state.bossHp)}%`;$('hero-fill').style.width=`${Math.max(0,state.hp)}%`;$('wrath-fill').style.width=`${state.wrath}%`;$('wrath-label').textContent=`${Math.floor(state.wrath)}%`;$('phase-label').textContent=state.index===8?`FORM ${state.phase} · THE LAST NAME`:`${state.phase===1?'DIVINE VIGIL':'UNBOUND FORM'} · PHASE ${state.phase}`}
let toastTimer;function showToast(t){let el=$('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1500)}
let captionTimer;function caption(t,ms=2000){const el=$('combat-caption');el.textContent=t;el.classList.add('show');clearTimeout(captionTimer);captionTimer=setTimeout(()=>el.classList.remove('show'),ms)}
function pause(){if(state.mode==='fight'){state.mode='paused';showScreen('pause-screen')}else if(state.mode==='paused'){state.mode='fight';showScreen('none')}}
$('begin-btn').onclick=()=>startChapter();$('fight-btn').onclick=beginFight;$('pause-btn').onclick=pause;$('resume-btn').onclick=pause;$('restart-btn').onclick=()=>startChapter();
$('next-btn').onclick=()=>{if(state.index>=8){state.index=0;localStorage.setItem('godfall-progress','0');state.mode='title';showScreen('title-screen');$('hud').classList.add('hidden');$('controls').classList.add('hidden');return}state.index++;localStorage.setItem('godfall-progress',String(state.index));startChapter()};

input.newString:
$('next-btn').onclick=()=>{if(state.index>=8){state.index=0;localStorage.setItem('godfall-progress','0');state.mode='title';showScreen('title-screen');$('hud').classList.add('hidden');$('controls').classList.add('hidden');return}state.index++;localStorage.setItem('godfall-progress',String(state.index));startChapter()};

const held=new Set();window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();held.add(k);state.keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'||k==='p')pause();if(state.mode==='fight'){if(k==='j'||k==='z')act('light');if(k==='k'||k==='x')act('heavy');if(k===' ')act('dodge');if(k==='shift')state.player.guard=true;if(k==='l'||k==='c')act('wrath')}});window.addEventListener('keyup',e=>{held.delete(e.key.toLowerCase());state.keys[e.key.toLowerCase()]=false;if(e.key==='Shift')state.player.guard=false});
function act(type){if(state.mode!=='fight')return;let p=state.player;if(type==='guard'){p.guard=true;return}if(type==='dodge'){if(p.attackCd>.48)return;p.anim='dodge';p.animT=.3;p.invuln=.48;p.x+=p.face*.35;p.z+=.04;state.shake=.04;return}if(type==='wrath'){if(state.wrath<35){showToast('WRATH NEEDS 35%');return}state.wrath-=35;p.anim='wrath';p.animT=.75;p.attackCd=.82;state.slow=.24;state.flash=.2;state.shake=.38;const d=deities[state.index];spawnBurst(p.x,p.z,d.color,24);let dist=Math.abs(p.x-state.boss.x);if(dist<1.6){damageBoss(24+state.index*1.3,true)}else{state.projectiles.push({x:p.x,z:p.z-.15,vx:(state.boss.x-p.x)*1.8,color:d.color,damage:18,life:1.2,size:.24})}caption(['CRIMSON WRATH','INFERNAL WRATH','VOID WRATH','CELESTIAL WRATH','ABSOLUTE WRATH'][Math.min(4,Math.floor(state.index/2))],1100);return}if(type==='light'||type==='heavy'){if(p.attackCd>.05)return;p.guard=false;p.comboT=1.1;p.combo=(p.combo%4)+1;p.anim=type==='heavy'?'heavy':'attack';p.animT=type==='heavy'?.47:.31;p.attackCd=type==='heavy'?.52:.32;p.face=state.boss.x>=p.x?1:-1;let reach=type==='heavy'?1.22:.94;let delta=state.boss.x-p.x;if(Math.abs(delta)<reach&&Math.abs(state.boss.z-p.z)<.43){let dmg=type==='heavy'?10:5.7;dmg*=1+Math.min(.5,state.index*.045);if(p.combo===4)dmg*=1.32;damageBoss(dmg);state.wrath=Math.min(100,state.wrath+(type==='heavy'?12:7));state.boss.stun=Math.max(state.boss.stun,type==='heavy'?.38:.21);state.boss.anim='hit';state.boss.animT=.22;state.shake=type==='heavy'?.17:.09;spawnBurst(state.boss.x,state.boss.z,deities[state.index].color,type==='heavy'?9:5);if(p.combo===4){caption(type==='heavy'?'DIVINE BREAK':'BLADE OF RUIN',700);state.boss.z-=.06}}else{p.x+=p.face*.11}}}
function damageBoss(n,heavy=false){state.bossHp=Math.max(0,state.bossHp-n);if(state.bossHp<50&&state.phase===1){state.phase=2;state.bossHp=Math.max(state.bossHp+8,20);state.boss.anim='transform';state.boss.animT=1.2;state.boss.stun=1.1;state.flash=.3;state.shake=.52;caption(`${deities[state.index].name} · UNBOUND FORM`,2200);showToast('THE DEITY REVEALS ITS TRUE FORM')}updateHud();if(state.bossHp<=0)victory()}
function victory(){state.mode='victory';state.boss.anim='fall';state.boss.animT=1.8;state.flash=.5;state.shake=.65;state.slow=.36;spawnBurst(state.boss.x,state.boss.z,deities[state.index].color,65);setTimeout(()=>{if(state.mode!=='victory')return;let d=deities[state.index];$('result-kicker').textContent=state.index===8?'THE CYCLE IS BROKEN':'DIVINITY BROKEN';$('result-title').textContent=state.index===8?'THE FIRST NAME':'A GOD FALLS';$('result-copy').textContent=state.index===8?'Vael remembers. He was the first maker, and the Nine were born from the fear that creation would end. He does not take the throne. He lets the worlds choose their own dawn.':'The divine form fractures. Beyond the falling light, a new rift opens—and another voice answers.';$('reward-name').textContent=d.reward;$('next-btn').innerHTML=state.index===8?'RETURN TO THE BEGINNING <span>↻</span>':'CONTINUE THE WAR <span>↗</span>';showScreen('result-screen');$('hud').classList.add('hidden');$('controls').classList.add('hidden')},1150)}
function spawnBurst(x,z,color,count){for(let i=0;i<count;i++){let a=Math.random()*Math.PI*2,s=.25+Math.random()*1.7;state.particles.push({x,y:0,z,vx:Math.cos(a)*s,vy:-.35-Math.random()*1.6,vz:Math.sin(a)*s,life:.45+Math.random()*.65,max:.8,size:2+Math.random()*6,color})}}
